import fs from "node:fs/promises";
import crypto from "node:crypto";
import { buildArtifactLocation, getArtifactDir } from "../shared/artifact-paths.js";
import { formatApprovalSummaryList, formatWorkflowLabel, renderArtifactCoverageLine, renderArtifactDocument, renderWorkflowLinkedSummaryLines } from "../shared/artifact-render.js";

export class ReviewArtifactManager {
  constructor({ config, stateStore }) {
    this.config = config;
    this.stateStore = stateStore;
    this.artifactDir = getArtifactDir(config, "agent-reviews");
  }

  async exportReviewArtifact({ reviewId, title, workflowId = "" }) {
    const review = reviewId
      ? await this.stateStore.getReview(reviewId)
      : (await this.stateStore.listReviews())[0] || null;
    const linkedWorkflow = workflowId ? await this.stateStore.getWorkflowRun(workflowId) : null;
    const linkedWorkflowArtifacts = workflowId ? await this.stateStore.listWorkflowArtifactsByWorkflow(workflowId) : [];
    const workflowBundle = workflowId ? await this.stateStore.getWorkflowBundle(workflowId) : null;

    if (!review) {
      throw new Error("No review record available to export.");
    }

    const createdAt = new Date().toISOString();
    const safeTitle = slugify(title || `${review.kind}-${review.status}`).slice(0, 80) || "review";
    const timestamp = createdAt.replace(/[:]/g, "-").replace(/\..+$/, "");
    const { absolutePath, storedPath } = buildArtifactLocation(this.config, "agent-reviews", `${timestamp}-${safeTitle}.md`);

    await fs.mkdir(this.artifactDir, { recursive: true });
    await fs.writeFile(
      absolutePath,
      renderReviewDocument({ review, title, createdAt, linkedWorkflow, linkedWorkflowArtifacts, workflowBundle }),
      "utf8"
    );

    const record = {
      id: `reviewartifact_${crypto.randomUUID()}`,
      createdAt,
      reviewId: review.id,
      reviewKind: review.kind,
      reviewStatus: review.status,
      title: title || `${review.kind} review`,
      path: storedPath,
      workflowId: workflowId || null
    };

    await this.stateStore.saveReviewArtifact(record);
    return record;
  }
}

function renderReviewDocument({ review, title, createdAt, linkedWorkflow, linkedWorkflowArtifacts, workflowBundle }) {
  return renderArtifactDocument({
    title: title || `${review.kind} review`,
    metadata: [
      `Generated at: ${createdAt}`,
      `Review id: ${review.id}`,
      `Kind: ${review.kind}`,
      `Target: ${review.target}`,
      `Status: ${review.status}`,
      `Workflow: ${formatWorkflowLabel(linkedWorkflow)}`,
      renderArtifactCoverageLine(linkedWorkflow?.dashboardSummary?.artifactCoverage)
    ],
    sections: [
      {
        title: "Summary",
        lines: [review.summary]
      },
      {
        title: "Findings",
        lines: review.findings?.length ? review.findings.map((item) => `- ${item}`) : ["- No findings recorded."]
      },
      {
        title: "Linked Records",
        lines: renderWorkflowLinkedSummaryLines({
          linkedWorkflow,
          linkedWorkflowArtifacts,
          includeReviewCount: false
        }).concat([
          `- Workflow approval summaries: ${formatApprovalSummaryList(workflowBundle?.approvalRequests || [])}`
        ])
      }
    ],
    notes: [
      "This file was generated by the coding-agent review artifact exporter.",
      "Export a fresh review artifact after rerunning a review if the evidence changes."
    ]
  });
}

function slugify(value) {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9\u4e00-\u9fa5]+/g, "-")
    .replace(/^-+|-+$/g, "");
}
